      expect(context.absolute('a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j'),
          r'C:\root\path\a\b\c\d\e\f\g\h\i\j');
      expect(
          context.absolute(
              'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k'),
