      expect(
          context.absolute('a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j',
              'k', 'l', 'm', 'n'),
          r'C:\root\path\a\b\c\d\e\f\g\h\i\j\k\l\m\n');
      expect(
          context.absolute('a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j',
